import requests

def test_put_api_auth_password_with_valid_bearer_token_and_new_password():
    base_url = "http://localhost:8000"
    endpoint = "/api/auth/password"
    url = base_url + endpoint
    token = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    new_password = "NewStrongP@ssw0rd123"

    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "Accept": "application/json"
    }
    json_payload = {
        "new_password": new_password
    }

    try:
        response = requests.put(url, headers=headers, json=json_payload, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed due to exception: {e}"

    assert response.status_code in (200, 204), f"Expected status code 200 or 204, got {response.status_code}"



test_put_api_auth_password_with_valid_bearer_token_and_new_password()
